record.field:
for rec in records.mapped('order_line').filtered(lambda l: l.printing):
    printing_note_id = env['printing.note'].search([('name', '=', rec.printing)], limit=1)
    if not printing_note_id:
        printing_note_id = env['printing.note'].create({'name': rec.printing})
    rec.write({'printing_note_id': printing_note_id.id})
